import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Start here: try it locally","description":"","frontmatter":{},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md","lastUpdated":1794405696000}`),a={name:`en/getting-started/quickstart.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="start-here-try-it-locally" tabindex="-1">Start here: try it locally <a class="header-anchor" href="#start-here-try-it-locally" aria-label="Permalink to “Start here: try it locally”">​</a></h1><h2 id="if-you-were-invited-to-the-admin-console" tabindex="-1">If you were invited to the admin console <a class="header-anchor" href="#if-you-were-invited-to-the-admin-console" aria-label="Permalink to “If you were invited to the admin console”">​</a></h2><p>You don&#39;t need to install anything. Open the invitation link and register a display name and a passkey. Continue to <a href="./../guides/accounts">sign-in and accounts</a>.</p><h2 id="if-you-are-installing-it-yourself" tabindex="-1">If you are installing it yourself <a class="header-anchor" href="#if-you-are-installing-it-yourself" aria-label="Permalink to “If you are installing it yourself”">​</a></h2><p>The recommended setup is to run on Cloudflare. It is easiest to follow if you first try the screens locally, then install into your own environment with <a href="./cloudflare">Cloudflare setup</a>.</p><h2 id="prerequisites-for-the-local-check" tabindex="-1">Prerequisites for the local check <a class="header-anchor" href="#prerequisites-for-the-local-check" aria-label="Permalink to “Prerequisites for the local check”">​</a></h2><ul><li>Node.js 24 or later, and npm</li><li>Git</li><li>A browser and device that support passkeys. Start with Chrome or Edge.</li></ul><p>Get the repository.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/manji6/jev-personalization.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev-personalization</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span></span></code></pre></div><h2 id="register" tabindex="-1">Register <a class="header-anchor" href="#register" aria-label="Permalink to “Register”">​</a></h2><p>Open <strong><code>http://localhost:4174/admin</code></strong>. Use this <code>localhost</code> spelling, not <code>127.0.0.1</code>.</p><p>Enter a display name, an email address and the local-only token below, then register a passkey.</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local-review-only-not-a-production-token</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Never use this value in production</p><p>This is a publicly known value for local checks. For the production ADMIN_TOKEN, set an independent random value created with a secrets management service or similar.</p></div><h2 id="what-really-works" tabindex="-1">What really works <a class="header-anchor" href="#what-really-works" aria-label="Permalink to “What really works”">​</a></h2><p>Passkey authentication, saving to the database, site permissions, campaign editing and offer display are all real. Only the Jev judgment is a stub, <code>local-review-stub</code>, which returns a score of 0.95. It does not connect to Jev or Cloudflare, and nothing is published.</p><p>A demo site is already registered. Create a campaign and, for the real-page preview URL, specify <strong><code>http://localhost:4174/demo</code></strong>. Set the target paths to all permitted pages or <code>/demo</code>.</p><h2 id="restart-and-stop" tabindex="-1">Restart and stop <a class="header-anchor" href="#restart-and-stop" aria-label="Permalink to “Restart and stop”">​</a></h2><p>Press Ctrl+C to stop. Accounts and settings stay in <code>data/review.sqlite</code> and are available after a restart. Don&#39;t delete this database if you need the history.</p><p>To start from a clean state, stop the server and point <code>REVIEW_DB_PATH</code> at a new database. You can also set <code>REVIEW_PORT</code> to change the port.</p><p>A passkey is bound to its origin and RP ID. Don&#39;t switch from localhost to another domain or an IP address partway through your check.</p><h2 id="open-help-from-the-admin-console" tabindex="-1">Open Help from the admin console <a class="header-anchor" href="#open-help-from-the-admin-console" aria-label="Permalink to “Open Help from the admin console”">​</a></h2><p>The sign-in screen has &quot;View Help and manual (「ヘルプ・マニュアルを見る」)&quot;. After signing in, you can open it from any screen through &quot;Help and manual (「ヘルプ・マニュアル」)&quot; in the side menu. On a smartphone it is the book icon. The home screen also has links to the setup and campaign-creation steps.</p><p>Help opens in a separate tab, so you can check it while keeping the settings you are in the middle of entering.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};